    import msvcrt

    def _lock_fd(fd: int) -> None:
        """Take a non-blocking exclusive lock on *fd*.

        Locks one byte at offset 0 of the file. Raises
        :class:`StateFileLocked` when another live process already holds that
        byte range; any other :class:`OSError` propagates to the caller.
        """
        try:
            os.lseek(fd, 0, os.SEEK_SET)
            msvcrt.locking(fd, msvcrt.LK_NBLCK, _WINDOWS_LOCK_BYTES)
        except OSError as error:
            if error.errno in (errno.EACCES, errno.EDEADLK):
                raise StateFileLocked() from None
            raise

    def _unlock_fd(fd: int) -> None:
        """Release the byte-range lock taken by :func:`_lock_fd` (best effort)."""
        try:
            os.lseek(fd, 0, os.SEEK_SET)
            msvcrt.locking(fd, msvcrt.LK_UNLCK, _WINDOWS_LOCK_BYTES)
        except OSError:
            pass

