    def _lock_fd(fd: int) -> None:
        """Take a non-blocking advisory ``flock`` (``LOCK_EX | LOCK_NB``).

        Raises :class:`StateFileLocked` when another live process already
        holds the lock; any other :class:`OSError` propagates to the caller.
